// Step 1: Deep search the incoming data to find the JSON text automatically
const item = $input.first().json;

function findInvoiceJson(obj) {
  if (typeof obj === 'string') {
    // Check if this string contains a JSON object structure
    if (obj.includes('{') && obj.includes('}')) {
      return obj;
    }
  }
  if (typeof obj === 'object' && obj !== null) {
    for (const key in obj) {
      const result = findInvoiceJson(obj[key]);
      if (result) return result;
    }
  }
  return null;
}

const rawStr = findInvoiceJson(item);
let parsed = {};

if (rawStr) {
  try {
    // Extract only the clean content between the first '{' and the last '}'
    const jsonMatch = rawStr.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[0]);
    }
  } catch (e) {
    // Backup fallback parsing method
    try {
      const cleaned = rawStr.replace(/```json|```/gi, '').trim();
      parsed = JSON.parse(cleaned);
    } catch (innerError) {
      throw new Error("Found the invoice text but failed to parse it into JSON: " + innerError.message);
    }
  }
}

// Safety check: If no data was found at all, stop and report it
if (!parsed || Object.keys(parsed).length === 0) {
  throw new Error("Could not find or extract any invoice data from the Gemini node output. Please verify that Gemini is returning text.");
}

// Helper formatters to clean numbers and text strings
const getFloat = (val) => {
  if (val == null) return '0.00';
  // Strip out any accidental currency symbols (like $) Gemini might have included
  const num = Number(String(val).replace(/[^0-9.-]/g, '')); 
  return isNaN(num) ? '0.00' : num.toFixed(2);
};

const getString = (val) => {
  if (val == null) return 'N/A';
  return String(val).trim();
};

// Step 2: Build your multi-line Markdown summary column
const markdown = `**Invoice Summary**
- **Invoice #:** ${getString(parsed.invoice_number || parsed.invoice)}
- **Vendor:** ${getString(parsed.vendor || parsed.vendor_name)}
- **Date:** ${getString(parsed.date)}
- **Due Date:** ${getString(parsed.due_date || parsed.due)}
- **Description:** ${getString(parsed.description)}
- **Subtotal:** $${getFloat(parsed.subtotal)}
- **Tax:** $${getFloat(parsed.tax)}
- **Total:** $${getFloat(parsed.total || parsed.total_amount)}
- **Status:** ${getString(parsed.status)}`;

// Step 3: Output keys matching your EXACT Google Sheet columns
return [{
  json: {
    "Invoice #": getString(parsed.invoice_number || parsed.invoice),
    "Vendor": getString(parsed.vendor || parsed.vendor_name),
    "Date": getString(parsed.date),
    "Due": getString(parsed.due_date || parsed.due),
    "Description": getString(parsed.description),
    "Subtotal": getFloat(parsed.subtotal),
    "Tax(25%)": getFloat(parsed.tax),
    "Total": getFloat(parsed.total || parsed.total_amount),
    "Status": getString(parsed.status || 'Unpaid'),
    "markdown": markdown
  },
  binary: $input.first().binary
}];
